using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

[TestClass]
public sealed class EvalTests : EvaluationTestBase
{
    private static ReportingConfiguration? s_reportingConfiguration;

    protected override ReportingConfiguration ReportingConfiguration =>
        s_reportingConfiguration ??= CreateReportingConfiguration();

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storage = new DiskBasedReportingStorage(Path.Combine("TestResults", "EvalReports"));
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
            new FluencyEvaluator(),
        };

        return new ReportingConfiguration(storage, evaluators);
    }

    protected override ChatConfiguration GetChatConfiguration()
    {
        var chatClient =
            new ChatClientBuilder(new OllamaChatClient(new Uri("http://localhost:11434"), "gpt-4o-mini"))
                .Build();

        return new ChatConfiguration(chatClient);
    }

    [TestMethod]
    public async Task ChatRespondsRelevantly()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await Chat.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        await Evaluate(messages, response);
    }
}

