using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "Reports");

    private static ChatConfiguration CreateChatConfiguration()
    {
        // Point this at your deployed model endpoint.
        // For local dev, set the CHAT_MODEL_ENDPOINT environment variable.
        var endpoint = Environment.GetEnvironmentVariable("CHAT_MODEL_ENDPOINT")
            ?? "http://localhost:5000";

        var chatClient = new OllamaChatClient(new Uri(endpoint), "gpt-4o-mini");
        return new ChatConfiguration(chatClient);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var chatConfig = CreateChatConfiguration();
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: StoragePath,
            evaluators: evaluators,
            chatConfiguration: chatConfig);
    }

    [TestMethod]
    public async Task ChatRespondsRelevantly()
    {
        var reportingConfig = CreateReportingConfiguration();

        await using var scenarioRun =
            await reportingConfig.CreateScenarioRunAsync("ChatRespondsRelevantly");

        var chatConfig = CreateChatConfiguration();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatConfig.ChatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var result = await scenarioRun.EvaluateAsync(messages, response);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(
                metric.Value.Interpretation?.Failed ?? false,
                $"Metric '{metric.Key}' failed: {metric.Value.Interpretation?.Reason}");
        }
    }

    [TestMethod]
    public async Task ChatHandlesFollowUp()
    {
        var reportingConfig = CreateReportingConfiguration();

        await using var scenarioRun =
            await reportingConfig.CreateScenarioRunAsync("ChatHandlesFollowUp");

        var chatConfig = CreateChatConfiguration();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
            new(ChatRole.Assistant, "The capital of France is Paris."),
            new(ChatRole.User, "What is its population?")
        };

        var response = await chatConfig.ChatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var result = await scenarioRun.EvaluateAsync(messages, response);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(
                metric.Value.Interpretation?.Failed ?? false,
                $"Metric '{metric.Key}' failed: {metric.Value.Interpretation?.Reason}");
        }
    }
}

